+/****************************************************************************
+ * BK7258 PM operation inter-core acknowledgement service.
+ *
+ * Armino's SARADC/PHY notify paths send START/END to CPU1 and wait no more
+ * than 5 ms for the mailbox-channel completion ACK.  This NuttX port already
+ * owns the same physical CPU0<->CPU1 mailbox through RPTUN.  Use a distinct
+ * magic and a shared subscriber rather than replacing RPTUN's doorbell.
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#ifdef CONFIG_BK7258_MAILBOX
+
+#include <stdbool.h>
+#include <stdint.h>
+
+#include <nuttx/clock.h>
+#include <nuttx/spinlock.h>
+
+#include <arm_internal.h>
+
+#include <common/bk_err.h>
+
+#include "include/bk7258_mailbox.h"
+#include "include/bk7258_memorymap.h"
+#include "include/bk7258_pm_ipc.h"
+
+#define BK7258_PM_IPC_ACK_BIT      UINT32_C(0x80000000)
+#define BK7258_PM_IPC_SERVICE_SHIFT 8
+#define BK7258_PM_IPC_SERVICE_MASK  UINT32_C(0xff)
+#define BK7258_PM_IPC_STATE_MASK    UINT32_C(0xff)
+#define BK7258_PM_IPC_ACK_TIMEOUT   5
+
+static spinlock_t g_bk7258_pm_ipc_lock = SP_UNLOCKED;
+static bool g_bk7258_pm_ipc_initialized;
+static bool g_bk7258_pm_ipc_waiting;
+static bool g_bk7258_pm_ipc_acked;
+static uint32_t g_bk7258_pm_ipc_expected;
+static uint8_t g_bk7258_pm_ipc_peer_state[2];
+
+static uint32_t bk7258_pm_ipc_token(uint8_t service, uint8_t state)
+{
+  return ((uint32_t)service << BK7258_PM_IPC_SERVICE_SHIFT) | state;
+}
+
+static bool bk7258_pm_ipc_cpu1_running(void)
+{
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  return (getreg32(BK7258_SYS_CPU_STATUS) &
+          (BK7258_SYS_CPU1_PWR_DW_STATE | BK7258_SYS_CPU1_HALTED_STATE |
+           BK7258_SYS_CPU1_RESET_STATE)) == 0;
+#else
+  return true;
+#endif
+}
+
+static void bk7258_pm_ipc_mbox_callback(uint8_t src_cpu, uint32_t token,
+                                         uint32_t magic, void *arg)
+{
+  irqstate_t flags;
+  uint8_t service;
+
+  (void)magic;
+  (void)arg;
+  service = (uint8_t)((token >> BK7258_PM_IPC_SERVICE_SHIFT) &
+                      BK7258_PM_IPC_SERVICE_MASK);
+  if (service > BK7258_PM_IPC_PHY)
+    {
+      return;
+    }
+
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  if (src_cpu != 1)
+    {
+      return;
+    }
+
+  if ((token & BK7258_PM_IPC_ACK_BIT) == 0)
+    {
+      return;
+    }
+
+  flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+  if (g_bk7258_pm_ipc_waiting && token ==
+      (g_bk7258_pm_ipc_expected | BK7258_PM_IPC_ACK_BIT))
+    {
+      g_bk7258_pm_ipc_acked = true;
+    }
+  spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+#else
+  if (src_cpu != 0 || (token & BK7258_PM_IPC_ACK_BIT) != 0)
+    {
+      return;
+    }
+
+  g_bk7258_pm_ipc_peer_state[service] =
+    (uint8_t)(token & BK7258_PM_IPC_STATE_MASK);
+  (void)bk7258_mbox_notify_magic(0, token | BK7258_PM_IPC_ACK_BIT,
+                                  BK7258_MBOX_PM_MAGIC);
+#endif
+}
+
+bk_err_t bk7258_pm_ipc_init(void)
+{
+  irqstate_t flags;
+  int ret;
+
+  flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+  if (g_bk7258_pm_ipc_initialized)
+    {
+      spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+      return BK_OK;
+    }
+  spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+
+  ret = bk7258_mbox_subscribe(BK7258_MBOX_PM_MAGIC,
+                              bk7258_pm_ipc_mbox_callback, NULL);
+  if (ret < 0)
+    {
+      return BK_FAIL;
+    }
+
+  flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+  g_bk7258_pm_ipc_initialized = true;
+  spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+  return BK_OK;
+}
+
+bk_err_t bk7258_pm_ipc_request(uint8_t service, uint8_t state)
+{
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  irqstate_t flags;
+  clock_t start;
+  uint32_t token;
+  int ret;
+
+  if (service > BK7258_PM_IPC_PHY || state > BK7258_PM_IPC_OP_END)
+    {
+      return BK_ERR_PARAM;
+    }
+
+  if (!bk7258_pm_ipc_cpu1_running())
+    {
+      /* Authority makes the same exemption when CPU1 is powered down. */
+      return BK_OK;
+    }
+
+  if (bk7258_pm_ipc_init() != BK_OK)
+    {
+      return BK_FAIL;
+    }
+
+  token = bk7258_pm_ipc_token(service, state);
+  flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+  if (g_bk7258_pm_ipc_waiting)
+    {
+      spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+      return BK_ERR_BUSY;
+    }
+
+  g_bk7258_pm_ipc_expected = token;
+  g_bk7258_pm_ipc_acked = false;
+  g_bk7258_pm_ipc_waiting = true;
+  spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+
+  ret = bk7258_mbox_notify_magic(1, token, BK7258_MBOX_PM_MAGIC);
+  if (ret < 0)
+    {
+      flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+      g_bk7258_pm_ipc_waiting = false;
+      spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+      return BK_FAIL;
+    }
+
+  start = clock_systime_ticks();
+  for (;;)
+    {
+      bool acked;
+
+      flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+      acked = g_bk7258_pm_ipc_acked;
+      if (acked)
+        {
+          g_bk7258_pm_ipc_waiting = false;
+        }
+      spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+      if (acked)
+        {
+          return BK_OK;
+        }
+
+      if (clock_systime_ticks() - start >= MSEC2TICK(BK7258_PM_IPC_ACK_TIMEOUT))
+        {
+          flags = spin_lock_irqsave(&g_bk7258_pm_ipc_lock);
+          g_bk7258_pm_ipc_waiting = false;
+          spin_unlock_irqrestore(&g_bk7258_pm_ipc_lock, flags);
+          return BK_FAIL;
+        }
+
+      up_udelay(10);
+    }
+#else
+  (void)service;
+  (void)state;
+  return BK_ERR_NOT_SUPPORT;
+#endif
+}
+
+bk_err_t bk7258_pm_ipc_saradc_init(void)
+{
+  return bk7258_pm_ipc_init();
+}
+
+bk_err_t bk7258_pm_ipc_phy_init(void)
+{
+  return bk7258_pm_ipc_init();
+}
+
+#else
+
+#include <common/bk_err.h>
+#include "include/bk7258_pm_ipc.h"
+
+bk_err_t bk7258_pm_ipc_init(void) { return BK_ERR_NOT_SUPPORT; }
+bk_err_t bk7258_pm_ipc_request(uint8_t service, uint8_t state)
+{
+  (void)service;
+  (void)state;
+  return BK_ERR_NOT_SUPPORT;
+}
+bk_err_t bk7258_pm_ipc_saradc_init(void) { return BK_ERR_NOT_SUPPORT; }
+bk_err_t bk7258_pm_ipc_phy_init(void) { return BK_ERR_NOT_SUPPORT; }
+
+#endif
